#!/usr/bin/env bash
set -euo pipefail

CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}"
STATE_DIR="${QS_STATE_DIR:-${XDG_STATE_HOME:-$HOME/.local/state}/serpantinum}"
SETTINGS_FILE="${QS_SETTINGS:-$CONFIG_DIR/serpantinum/settings.json}"
SOURCE_CSS="$STATE_DIR/discord/serpantinum.theme.css"

# Gracefully exit if source CSS generated by Matugen does not exist
if [[ ! -f "$SOURCE_CSS" ]]; then
    exit 0
fi

# Default theme settings
BORDER_RADIUS=8
BLUR_BACKGROUND="false"
BLUR_STYLE="blur"

# Allow positional argument overrides from Quickshell runtime: discord_sync.sh [radius] [blurBackground] [blurStyle]
if [[ $# -ge 3 ]]; then
    [[ -n "$1" && "$1" =~ ^[0-9]+$ ]] && BORDER_RADIUS="$1"
    [[ "$2" == "true" ]] && BLUR_BACKGROUND="true"
    [[ "$3" == "liquid" ]] && BLUR_STYLE="liquid"
# Safely extract settings if settings.json exists and is valid JSON
elif [[ -f "$SETTINGS_FILE" ]] && command -v jq >/dev/null 2>&1 && jq -e . "$SETTINGS_FILE" >/dev/null 2>&1; then
    val_radius="$(jq -r '.theme.borderRadius // empty' "$SETTINGS_FILE" 2>/dev/null || true)"
    if [[ -n "$val_radius" && "$val_radius" =~ ^[0-9]+$ ]]; then
        BORDER_RADIUS="$val_radius"
    fi

    val_blur_bg="$(jq -r '.theme.blurBackground // empty' "$SETTINGS_FILE" 2>/dev/null || true)"
    if [[ "$val_blur_bg" == "true" ]]; then
        BLUR_BACKGROUND="true"
    fi

    val_blur_style="$(jq -r '.theme.blurStyle // empty' "$SETTINGS_FILE" 2>/dev/null || true)"
    if [[ "$val_blur_style" == "liquid" ]]; then
        BLUR_STYLE="liquid"
    fi
fi

# Compute and render processed CSS template with Python for robust base64 wallpaper injection
TMP_PROCESSED="$(mktemp)"
trap 'rm -f "$TMP_PROCESSED"' EXIT

python3 - "$SOURCE_CSS" "$TMP_PROCESSED" "$BORDER_RADIUS" "$BLUR_BACKGROUND" "$BLUR_STYLE" << 'PYEOF'
import sys
import os
import io
import base64

source_css = sys.argv[1]
tmp_processed = sys.argv[2]
border_radius = sys.argv[3]
blur_bg = sys.argv[4]
blur_style = sys.argv[5]

is_liquid = (blur_bg == "true" and blur_style == "liquid")
is_blur = (blur_bg == "true" and blur_style != "liquid")

if blur_bg != "true":
    bg_opacity = "0.90"
    backdrop_blur = "none"
    island_border = "2px solid color-mix(in srgb, var(--serp-surface1) 75%, transparent)"
    island_shadow = "0 8px 24px rgba(0, 0, 0, 0.28)"
elif is_liquid:
    bg_opacity = "0.16"
    backdrop_blur = "blur(24px) saturate(190%) contrast(105%)"
    island_border = "2px solid color-mix(in srgb, var(--serp-primary) 50%, transparent)"
    island_shadow = "inset 0 1.5px 1.5px rgba(255, 255, 255, 0.20), inset 0 0 0 1px color-mix(in srgb, var(--serp-primary) 28%, transparent), 0 8px 32px rgba(0, 0, 0, 0.35)"
else:
    bg_opacity = "0.78"
    backdrop_blur = "blur(18px) saturate(140%)"
    island_border = "2px solid color-mix(in srgb, var(--serp-subtext1) 28%, transparent)"
    island_shadow = "0 8px 28px rgba(0, 0, 0, 0.32)"

wallpaper_url = "none"
window_bg = "none"

if not is_liquid:
    home = os.path.expanduser("~")
    cache_dir = os.path.join(home, ".cache/serpantinum/wallpaper")
    candidates = [os.path.join(cache_dir, "current_wallpaper.png")]
    if os.path.isdir(cache_dir):
        for f in os.listdir(cache_dir):
            if f.startswith("current_") and not f.endswith(".png") and not f.endswith(".json") and not f.endswith("_name"):
                fp = os.path.join(cache_dir, f)
                try:
                    with open(fp, "r", encoding="utf-8") as sf:
                        p = sf.read().strip()
                        if os.path.isfile(p):
                            candidates.append(p)
                except Exception:
                    pass

    target_wp = None
    for c in candidates:
        if os.path.isfile(c) and os.path.getsize(c) > 0:
            target_wp = c
            break

    if target_wp:
        try:
            from PIL import Image
            im = Image.open(target_wp).convert("RGB")
            im.thumbnail((1920, 1080), Image.Resampling.BILINEAR)
            buf = io.BytesIO()
            im.save(buf, format="JPEG", quality=75)
            b64 = base64.b64encode(buf.getvalue()).decode("ascii")
            wallpaper_url = f'url("data:image/jpeg;base64,{b64}")'
            window_bg = f'linear-gradient(color-mix(in srgb, var(--serp-base) 45%, transparent), color-mix(in srgb, var(--serp-base) 45%, transparent)), {wallpaper_url}'
        except Exception:
            window_bg = "color-mix(in srgb, var(--serp-base) 92%, transparent)"
    else:
        window_bg = "color-mix(in srgb, var(--serp-base) 92%, transparent)"

with open(source_css, "r", encoding="utf-8") as f:
    content = f.read()

content = content.replace("__BORDER_RADIUS__", str(border_radius))
content = content.replace("__BG_OPACITY__", bg_opacity)
content = content.replace("__BACKDROP_BLUR__", backdrop_blur)
content = content.replace("__ISLAND_BORDER__", island_border)
content = content.replace("__ISLAND_SHADOW__", island_shadow)
content = content.replace("__WALLPAPER_URL__", wallpaper_url)
content = content.replace("__WINDOW_BG__", window_bg)

with open(tmp_processed, "w", encoding="utf-8") as f:
    f.write(content)
PYEOF

# Helper to deploy theme file in-place to preserve inode for file watchers
deploy_theme() {
    local target_dir="$1"
    local target_file="$target_dir/serpantinum.theme.css"

    mkdir -p "$target_dir"
    if [[ -f "$target_file" ]]; then
        cat "$TMP_PROCESSED" > "$target_file"
    else
        cp -f "$TMP_PROCESSED" "$target_file"
    fi
    touch "$target_file"
}

deploy_quick_css() {
    local settings_dir="$1"
    local quick_css="$settings_dir/quickCss.css"

    mkdir -p "$settings_dir"

    python3 - "$quick_css" "$TMP_PROCESSED" << 'PYEOF'
import sys
import os
import re

quick_css_path = sys.argv[1]
processed_path = sys.argv[2]
start_marker = "/* === SERPANTINUM THEME START === */"
end_marker = "/* === SERPANTINUM THEME END === */"

with open(processed_path, "r", encoding="utf-8") as f:
    new_theme = f.read().strip()

user_css = ""
if os.path.isfile(quick_css_path):
    try:
        with open(quick_css_path, "r", encoding="utf-8") as f:
            content = f.read()
        pattern = re.compile(r'/\* === SERPANTINUM THEME START === \*/.*?/\* === SERPANTINUM THEME END === \*/\s*', re.DOTALL)
        user_css = pattern.sub('', content).strip()
    except Exception:
        pass

final_content = f"{start_marker}\n{new_theme}\n{end_marker}\n"
if user_css:
    final_content += f"\n{user_css}\n"

# In-place write to keep existing inode so Node.js inotify watch in Vencord does not die
mode = "r+" if os.path.exists(quick_css_path) else "w"
with open(quick_css_path, mode, encoding="utf-8") as f:
    f.seek(0)
    f.write(final_content)
    f.truncate()
    f.flush()
    os.fsync(f.fileno())

os.utime(quick_css_path, None)
PYEOF
}

# Deploy to Vencord themes and quickCss if Vencord directory exists
if [[ -d "$CONFIG_DIR/Vencord" ]]; then
    deploy_theme "$CONFIG_DIR/Vencord/themes"
    deploy_quick_css "$CONFIG_DIR/Vencord/settings"
fi

# Deploy to Vesktop themes and quickCss if vesktop directory exists
if [[ -d "$CONFIG_DIR/vesktop" ]]; then
    deploy_theme "$CONFIG_DIR/vesktop/themes"
    deploy_quick_css "$CONFIG_DIR/vesktop/settings"
fi

# Deploy to Flatpak Vesktop if present
FLATPAK_VESKTOP="$HOME/.var/app/dev.vencord.Vesktop/config/vesktop"
if [[ -d "$FLATPAK_VESKTOP" ]]; then
    deploy_theme "$FLATPAK_VESKTOP/themes"
    deploy_quick_css "$FLATPAK_VESKTOP/settings"
fi

# Safely patch settings.json to enable theme and transparent flag
patch_settings() {
    local target="$1"
    if [[ -f "$target" ]] && command -v jq >/dev/null 2>&1 && jq -e . "$target" >/dev/null 2>&1; then
        # If already enabled and transparent, do not rewrite settings.json (avoid disk I/O and race conditions)
        if jq -e '.transparent == true and ((.enabledThemes // []) | index("serpantinum.theme.css") != null)' "$target" >/dev/null 2>&1; then
            return 0
        fi

        local tmp="${target}.tmp.$$"
        local filter='.enabledThemes = (if ((.enabledThemes // []) | index("serpantinum.theme.css")) then .enabledThemes else ((.enabledThemes // []) + ["serpantinum.theme.css"]) end) | .transparent = true'
        if jq "$filter" "$target" > "$tmp" 2>/dev/null; then
            if jq -e . "$tmp" >/dev/null 2>&1; then
                mv -f "$tmp" "$target"
            else
                rm -f "$tmp"
            fi
        else
            rm -f "$tmp"
        fi
    fi
}

for settings_file in \
    "$CONFIG_DIR/Vencord/settings/settings.json" \
    "$CONFIG_DIR/Vencord/settings.json" \
    "$CONFIG_DIR/vesktop/settings/settings.json" \
    "$CONFIG_DIR/vesktop/settings.json" \
    "$FLATPAK_VESKTOP/settings/settings.json" \
    "$FLATPAK_VESKTOP/settings.json"; do
    if [[ -f "$settings_file" ]]; then
        patch_settings "$settings_file"
    fi
done
